// Resolve Google Drive URL para URL pública direta
function resolveUrl(url) {
  if (!url) return null;
  const match = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([^/?&]+)/);
  if (match) return `https://lh3.googleusercontent.com/d/${match[1]}`;
  return url;
}

// Converte data/hora de Brasília (UTC-3) para Unix timestamp UTC
function toUtcTimestamp(date, time) {
  const t = time || '09:00';
  const [y, m, d] = date.split('-').map(Number);
  const [h, min] = t.split(':').map(Number);
  return Math.floor(Date.UTC(y, m - 1, d, h + 3, min, 0) / 1000);
}

const body = $input.first().json.body;

if (!body.page_id || !body.page_token) {
  throw new Error('page_id e page_token são obrigatórios');
}

return [{
  json: {
    content_id:   body.content_id,
    caption:      body.caption || '',
    image_url:    resolveUrl(body.image_url),
    scheduled_ts: toUtcTimestamp(body.scheduled_date, body.scheduled_time),
    page_id:      body.page_id,
    page_token:   body.page_token,
    ig_account_id: body.ig_account_id || null,
  }
}];

const prep = $('Preparar Dados').first().json;
const tokenResp = $input.first().json;

const GRAPH = 'https://graph.facebook.com/v21.0';
const pageToken = tokenResp.access_token || prep.page_token;
const now = Math.floor(Date.now() / 1000);

// Valida se o agendamento é pelo menos 10 minutos no futuro
if (prep.scheduled_ts < now + 600) {
  const msg = 'Data de agendamento deve ser pelo menos 10 minutos no futuro';
  return [{ json: {
    content_id: prep.content_id,
    update: {},
    facebook:  { post_id: null, error: msg },
    instagram: { post_id: null, error: msg },
  }}];
}

// ── Facebook ───────────────────────────────────────────────────────
let fbPostId = null;
let fbError  = null;
try {
  const fbEndpoint = prep.image_url
    ? `${GRAPH}/${prep.page_id}/photos`
    : `${GRAPH}/${prep.page_id}/feed`;

  const fbParams = new URLSearchParams();
  fbParams.append('published', 'false');
  fbParams.append('scheduled_publish_time', String(prep.scheduled_ts));
  fbParams.append('access_token', pageToken);

  if (prep.image_url) {
    fbParams.append('url', prep.image_url);
    fbParams.append('caption', prep.caption);
  } else {
    fbParams.append('message', prep.caption);
  }

  const fbResp = await $helpers.httpRequest({
    method: 'POST',
    url: fbEndpoint,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: fbParams.toString(),
    returnFullResponse: true,
  });

  const fbData = typeof fbResp.body === 'string' ? JSON.parse(fbResp.body) : fbResp.body;
  fbPostId = fbData.id || null;
  fbError  = fbData.error?.message || null;
} catch (e) {
  fbError = String(e.message);
}

// ── Instagram ──────────────────────────────────────────────────────
let igPostId = null;
let igError  = null;

if (prep.ig_account_id && prep.image_url) {
  try {
    // Etapa 1: criar container de mídia
    const containerParams = new URLSearchParams();
    containerParams.append('image_url', prep.image_url);
    containerParams.append('caption', prep.caption);
    containerParams.append('published', 'false');
    containerParams.append('scheduled_publish_time', String(prep.scheduled_ts));
    containerParams.append('access_token', pageToken);

    const containerResp = await $helpers.httpRequest({
      method: 'POST',
      url: `${GRAPH}/${prep.ig_account_id}/media`,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: containerParams.toString(),
      returnFullResponse: true,
    });

    const containerData = typeof containerResp.body === 'string'
      ? JSON.parse(containerResp.body) : containerResp.body;

    if (containerData.error) {
      igError = containerData.error.message;
    } else if (containerData.id) {
      // Etapa 2: publicar container
      const publishParams = new URLSearchParams();
      publishParams.append('creation_id', containerData.id);
      publishParams.append('access_token', pageToken);

      const publishResp = await $helpers.httpRequest({
        method: 'POST',
        url: `${GRAPH}/${prep.ig_account_id}/media_publish`,
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: publishParams.toString(),
        returnFullResponse: true,
      });

      const publishData = typeof publishResp.body === 'string'
        ? JSON.parse(publishResp.body) : publishResp.body;

      igPostId = publishData.id || containerData.id;
      igError  = publishData.error?.message || null;
    }
  } catch (e) {
    igError = String(e.message);
  }
}

// ── Montar payload de update no Supabase ──────────────────────────
const update = {};
if (fbPostId) update.facebook_post_id  = fbPostId;
if (igPostId) update.instagram_post_id = igPostId;
if (fbPostId || igPostId) update.status = 'published';

return [{ json: {
  content_id: prep.content_id,
  update,
  facebook:  { post_id: fbPostId, error: fbError },
  instagram: { post_id: igPostId, error: igError },
}}];

